        // 1) 布隆过滤器先挡:未取消则直接放行
        if (!cancelRemindBloomFilter.contains(String.valueOf(Objects.hash(requestParam.getCouponTemplateId(), requestParam.getUserId(), requestParam.getRemindTime(), requestParam.getType())))) {
            return false;
        }

        // 2) 误判走 DB 兜底
